// 90 questões curadas em 3 trilhas temáticas (30 cada).
// Substitui o gerador procedural anterior (que produzia conteúdo fake).
// Dentro de cada trilha as questões progridem do conceitual ao prático.

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctIndex: number;
  explanation: string;
}

export type Trilha =
  | "eletronica" | "arduino" | "sensores"
  | "eletro_inter" | "arduino_inter" | "redes_inter"
  | "eletro_pro" | "firmware_pro" | "iot_pro";

export type Modulo = "basico" | "intermediario" | "pro";

