// Trilha 7 — Eletrônica Pro
const ELETRO_PRO: Question[] = [
  { id: "ep-01", text: "Em um par diferencial BJT, o CMRR é limitado principalmente por:", options: ["Resistência de carga do coletor", "Corrente de polarização do par e a simetria de casamento dos transistores", "A tensão de alimentação Vcc", "O capacitor de bypass do emissor"], correctIndex: 1, explanation: "CMRR = Ad/Ac. A rejeição de modo comum melhora com maior Re (resistor de emissor comum) e melhor casamento dos dois BJTs. Corrente de cauda constante (source de corrente) maximiza CMRR." },
  { id: "ep-02", text: "O resistor de ganho externo (Rg) de um amplificador de instrumentação INA128 define o ganho por:", options: ["G = 1 + Rg/50kΩ", "G = 1 + 50kΩ/Rg", "G = Rg/50kΩ", "G = 50kΩ × Rg"], correctIndex: 1, explanation: "INA128: G = 1 + 50 kΩ/Rg. Para G = 100, Rg = 50k/99 ≈ 505 Ω. O datasheet fornece a tabela. Valores de G de 1 a 10.000 são possíveis." },
  { id: "ep-03", text: "Em análise de Bode, uma margem de fase de 45° indica:", options: ["Sistema instável", "Sistema no limiar de instabilidade", "Sistema estável com resposta transitória aceitável (algum overshoot)", "Sistema criticamente amortecido sem overshoot"], correctIndex: 2, explanation: "Margem de fase > 45° é considerado projeto estável com transiente controlado. Margem < 30° pode oscilar. Margem = 0° → oscilação contínua. PM ideal: 45°–60°." },
  { id: "ep-04", text: "A topologia Sallen-Key de 2ª ordem permite implementar filtros ativos com:", options: ["Apenas um op-amp e RC", "Dois capacitores e dois resistores com um op-amp em ganho unitário, realizando polos complexos conjugados", "Somente filtros passa-alta", "Quatro op-amps"], correctIndex: 1, explanation: "Sallen-Key: 2R + 2C + 1 op-amp (buffer). Ajustando R e C, controla-se a frequência natural ωn e o fator de qualidade Q do filtro (Butterworth Q=0,707; Chebyshev Q>1)." },
  { id: "ep-05", text: "O fator de qualidade Q de um filtro passa-banda de 2ª ordem é definido como:", options: ["Q = ωn/BW", "Q = BW/ωn", "Q = ωn × BW", "Q = R/ωnL"], correctIndex: 0, explanation: "Q = fc/BW (fc = frequência central, BW = largura de banda a −3 dB). Alto Q = banda estreita e seletiva. Baixo Q = banda larga. Osciladores precisam Q muito alto para estabilidade." },
  { id: "ep-06", text: "Em um PLL (Phase-Locked Loop), o VCO ajusta sua frequência até:", options: ["A frequência de entrada ser zero", "A fase de saída ser idêntica à fase de referência — estado de lock com erro de fase estático mínimo", "A tensão de controle ser máxima", "O divisor de frequência travar"], correctIndex: 1, explanation: "PLL: detector de fase compara entrada e saída dividida. Erro de fase → tensão no filtro passa-baixa → tensão de controle do VCO → ajusta frequência → loop fecha." },
  { id: "ep-07", text: "A topologia flyback em SMPS usa transformador porque:", options: ["É mais eficiente que buck/boost", "Permite isolação galvânica entre entrada e saída e conversão de múltiplas tensões com um único switch", "Tem menor ripple de saída", "Opera apenas em alta frequência"], correctIndex: 1, explanation: "Flyback: energia armazenada no transformador (acoplador indutivo) durante ON, liberada para a carga durante OFF. Fornece isolação galvânica (segurança em equipamentos com 110/220V AC)." },
  { id: "ep-08", text: "O conversor LLC (série ressonante) é preferido para carregadores de alta potência porque:", options: ["Menor custo de componentes que buck simples", "Chaveamento em zero de corrente (ZCS) ou zero de tensão (ZVS) reduz drasticamente as perdas de switching, permitindo alta frequência e maior eficiência", "Não precisa de transformador", "Opera sem feedback de controle"], correctIndex: 1, explanation: "ZVS/ZCS: quando a transição ocorre com V=0 ou I=0, as perdas capacitivas de chaveamento (P = ½CV²f) são eliminadas. Carregadores LLC chegam a eficiência de 98%." },
  { id: "ep-09", text: "A norma CISPR 32 define limites de emissão eletromagnética para:", options: ["Equipamentos médicos", "Equipamentos multimídia (TVs, notebooks, roteadores) em faixas de frequência de 30 MHz a 1 GHz", "Cabos de alta tensão", "Apenas equipamentos industriais"], correctIndex: 1, explanation: "CISPR 32 (2012, substituiu CISPR 13 e 22): limites de emissão conduzida e irradiada para equipamentos de áudio/vídeo e TI. Classe B (residencial) é mais restrita que Classe A (industrial)." },
  { id: "ep-10", text: "Impedância de referência padrão para sistemas de RF é:", options: ["10 Ω", "75 Ω para TV a cabo, 50 Ω para RF genérico/instrumentação", "100 Ω diferencial", "120 Ω para RS-485"], correctIndex: 1, explanation: "50 Ω: padrão militar e instrumentação RF (compromisso entre potência máxima ~30 Ω e atenuação mínima ~77 Ω no coaxial). 75 Ω: mínima atenuação em cabo coaxial — padrão de TV a cabo." },
  { id: "ep-11", text: "O parâmetro S11 (coeficiente de reflexão de entrada) em −20 dB indica:", options: ["Alta reflexão — ruim", "1% da potência refletida — boa casamento de impedância", "Ganho de 20 dB", "Perda de inserção de 20 dB"], correctIndex: 1, explanation: "S11 em dB = 20·log10(|Γ|). S11 = −20 dB → |Γ| = 0,1 → 1% de potência refletida. S11 < −10 dB geralmente é aceitável; < −20 dB é excelente." },
  { id: "ep-12", text: "Amplificadores Classe D usam chaveamento em vez de transistor linear porque:", options: ["São mais simples de projetar", "Eficiência teórica de 100% — transistores em saturação ou corte dissipam pouca energia, ao contrário da classe A/B que opera na região linear", "Produzem menos distorção", "Operam em baixa frequência"], correctIndex: 1, explanation: "Classe A: eficiência ~25%. Classe AB: ~50–70%. Classe D: chaveamento PWM + filtro LC de saída → eficiência 90–98%. Presente em todas os amplificadores de áudio modernos de alta potência." },
  { id: "ep-13", text: "Dead-time em amplificador Classe D é necessário para evitar:", options: ["Distorção harmônica", "Shoot-through: condução simultânea dos transistores high-side e low-side causando curto-circuito da fonte", "Ruído de chaveamento", "Sobretensão no indutor de saída"], correctIndex: 1, explanation: "Shoot-through queima os transistores de potência instantaneamente. Dead-time de 20–100 ns garante que um transistor esteja completamente desligado antes do outro ligar." },
  { id: "ep-14", text: "A densidade espectral de ruído de um op-amp em V/√Hz caracteriza:", options: ["O ruído total integrado em toda a banda", "O ruído por raiz quadrada da largura de banda — permite calcular ruído total para qualquer BW: Vn_total = en × √BW", "A temperatura de operação máxima", "A corrente de bias de entrada"], correctIndex: 1, explanation: "Se en = 5 nV/√Hz e BW = 10 kHz: Vn = 5 × √10000 = 500 nV RMS. Amplificadores de precisão têm en < 1 nV/√Hz (ex.: AD797: 0,9 nV/√Hz)." },
  { id: "ep-15", text: "Bandgap reference (referência de bandgap de silício) fornece tensão estável de:", options: ["1,0 V com coeficiente zero ppm/°C", "~1,25 V com baixíssimo drift térmico (tipicamente ±10–50 ppm/°C)", "Vcc/2 em qualquer temperatura", "5 V estabilizados"], correctIndex: 1, explanation: "Tensão de bandgap do Si: ~1,205 V. Circuitos bandgap (como LM336, ADR445) usam compensação de temperatura para cancelar os coeficientes térmicos, resultando em referências de alta estabilidade." },
  { id: "ep-16", text: "O que é SNR (Signal-to-Noise Ratio) e como afeta a resolução efetiva do ADC?", options: ["Relação tensão de referência / tensão de saída", "Relação entre potência do sinal desejado e potência de ruído. SNR determina o ENOB: ENOB = (SNR_dB − 1,76) / 6,02", "Temperatura de ruído do conversor", "Frequência máxima do sinal de entrada"], correctIndex: 1, explanation: "ENOB (Effective Number of Bits): ADC de 12 bits com SNR = 68 dB → ENOB = (68−1,76)/6,02 ≈ 11 bits. Ruído reduz bits efetivos. SNR ideal de ADC N bits = 6,02N + 1,76 dB." },
  { id: "ep-17", text: "ADC Delta-Sigma (ΔΣ) consegue alta resolução (20–24 bits) usando:", options: ["Múltiplos comparadores em paralelo (Flash ADC)", "Oversampling a alta frequência (muito acima de Nyquist) combinado com noise shaping e decimação digital", "Banco de resistores precisos", "PLL para geração de clock estável"], correctIndex: 1, explanation: "ΔΣ: amostragem a 256× ou 512× a taxa Nyquist. Modulador move o ruído para alta frequência; filtro decimador elimina. Resolução efetiva cresce 3 dB a cada dobramento da taxa de oversampling." },
  { id: "ep-18", text: "O que é current mirror e qual é sua aplicação principal?", options: ["Espelho óptico para alinhamento de laser", "Circuito com 2 transistores que replica com precisão uma corrente de referência para fornecer corrente constante em outro ramo", "Driver de corrente para LED de alta potência apenas", "Circuito de proteção contra curto-circuito"], correctIndex: 1, explanation: "Current mirror: transistor Q1 é diodo-conectado (Vbe = Vref); Q2 tem mesmo Vbe → mesma Ic. Usado como carga ativa em pares diferenciais, fontes de corrente de polarização e DACs." },
  { id: "ep-19", text: "A resistência térmica junção-ambiente (θJA) de um componente semicondutor é usada para:", options: ["Calcular a condutividade do material semicondutor", "Calcular a temperatura da junção: Tj = Ta + P × θJA, onde P é a potência dissipada", "Determinar a frequência máxima de operação", "Especificar o tipo de encapsulamento"], correctIndex: 1, explanation: "Se θJA = 40 °C/W, Ta = 25°C e P = 2W: Tj = 25 + 2×40 = 105°C. Tjmax típico é 125–150°C. Se Tj > Tjmax, o componente falha ou ativa proteção térmica." },
  { id: "ep-20", text: "Charge pump (bomba de carga) gera tensão maior ou negativa porque:", options: ["Usa um transformador de alta frequência", "Usa capacitores chaveados para transferir carga: em cada ciclo, um capacitor é carregado e depois conectado em série com Vcc, efetivamente somando tensões", "Usa o efeito piezoelétrico", "É baseado em energia de RF captada pela antena"], correctIndex: 1, explanation: "Charge pump dobrador: C vola para Vcc durante ON; durante OFF, C é conectado em série com Vcc → saída = 2×Vcc. Sem indutor! Usado em flash de câmera, LCD de contraste negativo, RS-232 ±12V." },
  { id: "ep-21", text: "O que é pre-compliance EMC scan antes de testes formais?", options: ["Apenas verificação visual de PCB", "Uso de analisador de espectro + antena para identificar frequências problemáticas de emissão antes de submeter ao laboratório acreditado, economizando iterações caras", "Teste de EMI feito pelo fabricante do chip", "Calibração de ferrite beads"], correctIndex: 1, explanation: "Pre-compliance: identifica problemas (harmônicos de clock, chaveamento SMPS, etc.) antes do teste formal. Uma reprovação em laboratório acreditado pode custar R$30.000+; pré-scans detectam 80% dos problemas." },
  { id: "ep-22", text: "Para um op-amp a funcionar na faixa de 1 V a 99 V com alimentação única de 100 V, é necessário um:", options: ["Op-amp de rail-to-rail", "Op-amp convencional — ele opera desde 0 V até Vcc sem restrições", "Amplificador de instrumentação apenas", "Op-amp single-supply com Vos calibrado"], correctIndex: 0, explanation: "Op-amp convencional não opera próximo aos trilhos de alimentação (típico 1–2 V de headroom). Rail-to-rail de entrada e saída (RRIO) alcança de 0 V a Vcc nas entradas e saída — essencial em sistemas single-supply." },
  { id: "ep-23", text: "A técnica de 'star ground' em PCB serve para:", options: ["Criar um padrão visual atraente na placa", "Conectar todos os retornos de corrente em um único ponto de referência central, evitando loops de terra com diferentes impedâncias que causam ruído diferencial", "Distribuir alimentação de forma equilibrada", "Blindar sinais de RF"], correctIndex: 1, explanation: "Star ground: cada subsistema (digital, analógico, potência) tem seu próprio retorno; todos convergem em um ponto único. Evita que correntes ruidosas do digital criem diferencial de tensão no terra analógico." },
  { id: "ep-24", text: "A tensão de saída de um ADC SAR (Successive Approximation Register) de N bits é determinada em:", options: ["N ciclos de clock (um bit por ciclo, do MSB ao LSB)", "2^N ciclos de clock", "Um único ciclo de clock com N comparadores", "N² ciclos de clock"], correctIndex: 0, explanation: "ADC SAR: começa testando o MSB (V = Vref/2). Se ≥, bit=1; se <, bit=0. Repete para cada bit em sequência. Total: N conversões = N ciclos de clock. MCP3208 de 12 bits: 12 ciclos SPI." },
  { id: "ep-25", text: "O que é 'ringing' em sinais digitais de alta velocidade?", options: ["Ruído térmico nas trilhas", "Oscilação transitória após borda causada por reflexões de descasamento de impedância em linhas de transmissão", "Interferência de 60 Hz da rede elétrica", "Modulação de amplitude indesejada"], correctIndex: 1, explanation: "Ringing ocorre quando a impedância da trilha != impedância de carga. Terminação série (resistor na fonte, tipicamente 33–100 Ω) amortece reflexões. Crítico em DDR, LVDS, PCIe." },
  { id: "ep-26", text: "O que é 'ground bounce' em circuitos digitais de alta velocidade?", options: ["Variação de tensão no barramento de dados", "Flutuação do potencial de terra causada pela indutância parasita dos leads/vias de GND quando múltiplos drivers chaveiam simultaneamente (SSN — Simultaneous Switching Noise)", "Ruído acústico gerado pelo circuito", "Variação de temperatura do plano de terra"], correctIndex: 1, explanation: "Ground bounce: L × dI/dt. Quando N drivers chaveiam ao mesmo tempo, a corrente total dI/dt × Lgnd cria uma tensão que faz o GND 'saltar'. Solução: decoupling local e menor indutância de GND." },
  { id: "ep-27", text: "O que é MOSFET gate charge (Qg) e por que importa para drivers?", options: ["Carga estática acumulada na gate durante fabricação", "Carga total necessária para levar a gate de 0 a Vgs_drive; determina a corrente de pico e potência de drive: Pdriver = Qg × Vgs × fsw", "Isolamento dielétrico do gate", "Corrente de fuga do gate"], correctIndex: 1, explanation: "Gate charge alta (ex.: 150 nC em IGBT de potência) exige driver de corrente alta para chaveamento rápido: Idriver = Qg/t_sw. MOSFET de RF têm Qg < 1 nC; IGBTs de kW têm Qg de centenas de nC." },
  { id: "ep-28", text: "A modulação SPWM (Sinusoidal PWM) em inversores de frequência gera:", options: ["Saída DC a partir de entrada AC", "Sinal de saída PWM cuja largura de pulso varia senoidalmente, de forma que o fundamental AC é recuperado pelo motor (carga indutiva) com baixa distorção harmônica", "Tensão quadrada na saída da carga", "Apenas harmônicos de alta frequência"], correctIndex: 1, explanation: "SPWM: portadora triangular comparada com senoidal de referência. Duty cycle varia senoidalmente. Motor filtra harmonicos altos. THD depende do índice de modulação e frequência de portadora." },
  { id: "ep-29", text: "Para medir corrente em alta tensão com isolação galvânica, o sensor mais adequado é:", options: ["Resistor shunt", "Divisor de tensão", "Sensor de efeito Hall (ex.: ACS712, LEM) com isolamento integrado", "Termistor na trilha de potência"], correctIndex: 2, explanation: "Hall sensor: campo magnético gerado pela corrente é medido por elemento Hall isolado galvanicamente. Mede AC e DC, suporta picos, sem perda resistiva. Shunts: baixo custo mas sem isolação." },
  { id: "ep-30", text: "Qual é a frequência de ressonância de um circuito LC série com L=100µH e C=100nF?", options: ["~50 kHz", "~100 kHz", "~159 kHz", "~200 kHz"], correctIndex: 2, explanation: "f = 1/(2π√(LC)) = 1/(2π√(100µ × 100n)) = 1/(2π × 100µ) ≈ 1/(628µ) ≈ 159 kHz." },
];

// Trilha 8 — Firmware Avançado
const FIRMWARE_PRO: Question[] = [
  { id: "fp-01", text: "O ARM Cortex-M4 usa qual arquitetura de instrução?", options: ["ARMv6-M (Thumb)", "ARMv7-M com Thumb-2 e extensão DSP/FPU opcional", "ARMv8-A (64-bit)", "RISC-V RV32I"], correctIndex: 1, explanation: "Cortex-M4: ARMv7E-M com Thumb-2 (instruções 16 e 32 bits misturadas), extensão DSP (SIMD) e FPU de precisão simples (opcional). Pipeline de 3 estágios com especulação de branch." },
  { id: "fp-02", text: "O vetor de reset em ARM Cortex-M aponta para:", options: ["O endereço 0x00000000 diretamente", "A tabela de vetores em 0x00000000: [0]=valor inicial do SP, [1]=endereço da função Reset_Handler", "A função main()", "O bootloader em 0x1FFF0000"], correctIndex: 1, explanation: "Ao resetar, o Cortex-M lê [0x00000000] como valor do stack pointer e [0x00000004] como endereço do Reset_Handler. O vetor de exceções começa aqui (ou no valor de VTOR)." },
  { id: "fp-03", text: "O que é o NVIC (Nested Vectored Interrupt Controller) no Cortex-M?", options: ["Controlador de acesso à memória Flash", "Periférico que gerencia até 240 interrupções externas com prioridades configuráveis, suportando interrupções aninhadas (de maior prioridade interrompem as de menor)", "Módulo de FPU (ponto flutuante)", "Interface para debugger externo via JTAG"], correctIndex: 1, explanation: "NVIC: cada interrupção tem prioridade (0 = mais alta). ISR de prioridade 2 pode ser interrompida por ISR de prioridade 1. Número de bits de prioridade varia: Cortex-M0 tem 2, M4 pode ter 8 bits." },
  { id: "fp-04", text: "Em um linker script (.ld) para ARM, a seção .data contém:", options: ["Código executável da aplicação", "Variáveis globais inicializadas — armazenadas na Flash e copiadas para SRAM pelo startup code no boot", "Strings de debug em Flash apenas", "Interruptores de vetor"], correctIndex: 1, explanation: ".text = código e constantes na Flash. .data = variáveis globais inicializadas (ex.: int x = 5), copiadas Flash→SRAM no startup. .bss = variáveis não inicializadas (zeradas no startup)." },
  { id: "fp-05", text: "O startup code em ARM Cortex-M executa antes de main() e é responsável por:", options: ["Apenas inicializar o PLL de clock", "Inicializar SP, copiar .data de Flash para SRAM, zerar .bss, chamar construtores C++ (__libc_init_array) e chamar main()", "Configurar os pinos GPIO iniciais", "Carregar o sistema operacional"], correctIndex: 1, explanation: "Startup típico: seta SP → copia .data (LMA→VMA) → limpa .bss → chama __libc_init_array() (C++ static constructors) → chama SystemInit() → entra em main(). Fornecido pelo fabricante ou CMSIS." },
  { id: "fp-06", text: "O que é HAL vs LL (Low Layer) em STM32CubeMX?", options: ["HAL é para STM32F0, LL para STM32H7", "HAL: abstração portável e de alto nível; LL: acesso direto a registradores com performance máxima e código menor. Podem ser misturados por periférico", "HAL usa DMA, LL não", "São bibliotecas de terceiros, não da ST"], correctIndex: 1, explanation: "HAL: fácil portabilidade, overhead de software. LL: gerado por CubeMX, acessa registradores diretamente (sem overhead), ideal para periféricos de tempo crítico (SPI rápido, ADC contínuo)." },
  { id: "fp-07", text: "DMA (Direct Memory Access) libera a CPU porque:", options: ["Opera em frequência de clock maior que a CPU", "Transfere dados entre periférico e memória automaticamente sem intervenção da CPU; CPU é notificada ao final via interrupção", "Usa um processador dedicado embutido na CPU", "É executado pelo FPU em paralelo"], correctIndex: 1, explanation: "Sem DMA: CPU lê cada byte do ADC/SPI um a um. Com DMA: configura-se source, destination, tamanho; DMA transfere sozinho (burst ou incrementando endereço); interrupção HT/TC ao terminar." },
  { id: "fp-08", text: "DMA em modo circular com buffer duplo (double-buffer) é usado para:", options: ["Dobrar a largura de banda de memória", "Processar metade do buffer enquanto o DMA preenche a outra metade — zero-copy, sem parar o stream (ex.: DAC de áudio, ADC contínuo)", "Apenas em transferências de SPI", "Reduzir consumo de energia"], correctIndex: 1, explanation: "Half-Transfer interrupt: DMA preencheu metade → CPU processa primeira metade. Transfer Complete: DMA preencheu segunda metade → CPU processa segunda metade. Fluxo contínuo sem perda." },
  { id: "fp-09", text: "No protocolo USB, o descritor de dispositivo inclui:", options: ["Apenas o endereço USB do dispositivo", "VendorID (VID), ProductID (PID), versão USB, classe do dispositivo, número de configurações — identifica o dispositivo ao host", "O conteúdo dos endpoints", "As permissões de acesso do driver"], correctIndex: 1, explanation: "USB enumeration: host lê Device Descriptor (18 bytes: bLength, bDescriptorType, bcdUSB, bDeviceClass, VID, PID...). VID/PID identificam o driver. CDC (serial virtual) usa class 0x0A." },
  { id: "fp-10", text: "CAN bus (Controller Area Network) usa NRZ com bit stuffing porque:", options: ["Para garantir sincronização de clock entre nós — após 5 bits consecutivos iguais, um bit complementar é inserido automaticamente", "Para comprimir dados e aumentar throughput", "É o único método compatível com ISO 11898", "Para detectar falhas elétricas no cabo"], correctIndex: 0, explanation: "CAN NRZ: sem clock separado, usa transições do sinal para sincronismo. Bit stuffing força transições: a cada 5 bits iguais, insere-se 1 bit oposto. O receptor descarta bits de stuffing." },
  { id: "fp-11", text: "CAN bus com taxa de 1 Mbit/s tem comprimento máximo de cabo de aproximadamente:", options: ["1 km", "100 m", "40 m", "10 m"], correctIndex: 2, explanation: "Relação bit-rate × comprimento ≈ 50 Mbit/s·m. A 1 Mbps: máximo ~40 m. A 125 kbps: ~500 m. A 10 kbps: ~6 km. A propagação do sinal deve completar ida e volta em 1 bit period." },
  { id: "fp-12", text: "O que é Modbus RTU e qual é sua diferença para Modbus TCP?", options: ["RTU é mais novo e usa Ethernet; TCP é legado e usa RS-232", "RTU: comunicação serial (RS-485/RS-232) com CRC-16 binário compacto; TCP: mesmo protocolo mas encapsulado em pacotes TCP/IP na porta 502", "São protocolos incompatíveis entre si", "RTU opera apenas em half-duplex; TCP é full-duplex"], correctIndex: 1, explanation: "Modbus RTU: frame = endereço(1) + função(1) + dados(N) + CRC(2). Sobre RS-485 multidrop até 32 dispositivos. Modbus TCP: adiciona MBAP header (7 bytes) e remove CRC (o TCP garante integridade)." },
  { id: "fp-13", text: "Em FreeRTOS, qual é a diferença entre xQueueSend() e xQueueSendFromISR()?", options: ["Nenhuma — são aliases", "xQueueSend() pode bloquear esperando espaço na fila; xQueueSendFromISR() nunca bloqueia — usa pxHigherPriorityTaskWoken para solicitar context switch após ISR", "xQueueSendFromISR() só funciona com DMA", "xQueueSend() é mais rápida para ISRs"], correctIndex: 1, explanation: "ISRs não podem chamar funções que bloqueiem. xQueueSendFromISR() é não-bloqueante; se acordar task de prioridade maior, seta pxHigherPriorityTaskWoken=pdTRUE e o portYIELD_FROM_ISR() ao sair faz o context switch." },
  { id: "fp-14", text: "FreeRTOS heap_4 difere do heap_1 porque:", options: ["heap_4 não usa malloc", "heap_4 suporta pvPortFree() com coalescência de blocos livres adjacentes; heap_1 é simples e não libera memória (sem free)", "heap_4 usa FLASH em vez de SRAM", "heap_4 é apenas para Cortex-M4"], correctIndex: 1, explanation: "heap_1: apenas pvPortMalloc(), sem free — determinístico, para sistemas que só alocam no init. heap_4: malloc+free com coalescência para evitar fragmentação. heap_5: spans múltiplas regiões de memória descontínuas." },
  { id: "fp-15", text: "Para implementar bootloader em ARM Cortex-M que pula para a aplicação, o procedimento é:", options: ["Apenas alterar o PC para o endereço da aplicação via GOTO", "Setar o SP com o valor em [APP_ADDR], ajustar VTOR para APP_ADDR, setar o PC com o valor em [APP_ADDR+4] e desabilitar/limpar periféricos do bootloader antes", "Fazer reset de hardware via NVIC SystemReset()", "Chamar a função main() da aplicação diretamente"], correctIndex: 1, explanation: "Bootloader jump: 1) sp = *(APP_BASE); 2) SCB->VTOR = APP_BASE; 3) reset_handler = *(APP_BASE+4); 4) (*reset_handler)(). Não fazer SystemReset() — isso reinicia do bootloader novamente." },
  { id: "fp-16", text: "O que é CRC-32 e como é usado para integridade de firmware?", options: ["Compressão de firmware", "Função hash polinomial de 32 bits: detecta erros de transmissão/armazenamento com probabilidade de miss < 1/2^32. Calculada sobre o binário e armazenada no cabeçalho do firmware para verificação no boot", "Criptografia de firmware AES", "Soma simples de todos os bytes do firmware"], correctIndex: 1, explanation: "Bootloader calcula CRC-32 do firmware recebido e compara com CRC armazenado. Se difere → firmware corrompido → não executa. STM32 tem acelerador CRC-32 em hardware (HWCRC)." },
  { id: "fp-17", text: "O que é TrustZone em ARM Cortex-M33 e como divide o sistema?", options: ["Apenas um registrador de proteção de memória (MPU)", "Extensão de segurança que divide o SoC em mundo Secure (acessa todos os recursos) e Non-Secure (acesso restrito), com transições controladas por NSC (Non-Secure Callable) entries", "Um módulo de criptografia AES embutido", "Um hypervisor de RTOS integrado no hardware"], correctIndex: 1, explanation: "TrustZone-M: Secure World executa código de boot, chaves, crypto. Non-Secure World executa aplicação. Memória particionada via SAU/IDAU. PSA (Platform Security Architecture) da Arm se baseia em TrustZone." },
  { id: "fp-18", text: "O registrador SysTick no Cortex-M é tipicamente usado para:", options: ["Gerar interrupção de ADC", "Base de tempo do RTOS — interrupção periódica (ex.: 1 ms) para preempção de tasks pelo scheduler", "Medir temperatura do SoC", "Controlar o DMA"], correctIndex: 1, explanation: "SysTick: timer de 24 bits decrescente. FreeRTOS usa SysTick como tick source padrão (configTICK_RATE_HZ). A ISR SysTick_Handler incrementa o tick count e dispara o scheduler se necessário." },
  { id: "fp-19", text: "O SWO (Single Wire Output) em ARM Cortex-M é usado para:", options: ["Comunicação serial de aplicação", "Saída de trace de baixo overhead via ITM (Instrumentation Trace Macrocell) — permite printf-style debug sem impactar tempo real, usando apenas 1 pino", "Programação do bootloader", "Configuração do PLL"], correctIndex: 1, explanation: "SWO: ITM printf usa um pino SWO além dos 4 pinos JTAG. Keil µVision, STM32CubeIDE e OpenOCD exibem as mensagens em tempo real. Overhead mínimo comparado com UART." },
  { id: "fp-20", text: "O que é CMSIS-DSP e qual sua utilidade?", options: ["Biblioteca de sistema operacional da Arm", "Biblioteca de funções de processamento de sinais digitais (FFT, filtros FIR/IIR, operações matriciais, estatísticas) otimizadas para instruções SIMD do Cortex-M4/M7", "Protocolo de comunicação para sensores", "Driver de display LCD"], correctIndex: 1, explanation: "CMSIS-DSP: arm_rfft_fast_f32() (FFT radix-4), arm_fir_f32() (FIR), arm_biquad_cascade_df2T_f32() (IIR cascata). Usa instruções SIMD do Cortex-M4 para operações que processam múltiplos dados por instrução." },
  { id: "fp-21", text: "Em USB HID, o report descriptor define:", options: ["A velocidade de transferência USB", "O formato dos dados trocados (reports): quais campos, tamanhos em bits, unidades, min/max de cada valor (ex.: eixo X: 16 bits, -32768 a 32767)", "O VID/PID do dispositivo", "O número de endpoints USB"], correctIndex: 1, explanation: "HID report descriptor: sequência de itens (Usage Page, Usage, Logical Minimum/Maximum, Report Size, Report Count, Input/Output). Ex.: mouse: X(8b), Y(8b), botões(3b), padding(5b). Driver HID genérico interpreta." },
  { id: "fp-22", text: "O estado 'Bus-Off' no CAN bus ocorre quando:", options: ["O nó está sem alimentação", "O TEC (Transmit Error Counter) ultrapassa 255, fazendo o nó sair do barramento automaticamente para evitar que continue contaminando a comunicação", "O cabo está desconectado (open circuit)", "Todos os nós estão em modo sleep"], correctIndex: 1, explanation: "CAN error handling: Error Active (TEC<128), Error Passive (128≤TEC<256), Bus-Off (TEC≥256). Em Bus-Off, o nó silencia por 128 sequências de 11 bits recessivos antes de tentar recuperação." },
  { id: "fp-23", text: "Flash programming em microcontroladores ARM geralmente requer que a função de gravação execute em:", options: ["Qualquer local de memória", "SRAM — porque a Flash não pode ser lida (execução de código) e escrita simultaneamente; a função de gravação deve estar em RAM", "Registradores específicos do Cortex-M", "O bootloader em ROM"], correctIndex: 1, explanation: "STM32: HAL_FLASH_Program() deve ser executado de RAM (ou de outra bank em Flash dupla). A gravação de uma página apaga e re-escreve — impossível buscar instrução e gravar simultaneamente." },
  { id: "fp-24", text: "FreeRTOS event groups permitem uma task esperar por:", options: ["Apenas um evento por vez", "Combinação de múltiplos eventos (bits) — ANY (OR) ou ALL (AND) — antes de ser desbloqueada", "Eventos apenas de interrupções", "Mensagens de alta prioridade somente"], correctIndex: 1, explanation: "xEventGroupWaitBits(grp, BIT_A|BIT_B, pdTRUE, pdTRUE, pdMS_TO_TICKS(1000)): bloqueia até BIT_A E BIT_B serem setados (pdTRUE=AND). pdFALSE no 4° param → OR (qualquer um dos bits). Essencial para sincronização múltipla." },
  { id: "fp-25", text: "Stack overflow em FreeRTOS pode ser detectado com:", options: ["Apenas depurador externo (JTAG)", "configCHECK_FOR_STACK_OVERFLOW=2: verifica padrão de bytes no final da stack a cada context switch, chamando vApplicationStackOverflowHook() ao detectar overflow", "Apenas inspeção manual de código", "MPU (Memory Protection Unit) exclusivamente"], correctIndex: 1, explanation: "FreeRTOS preenche a stack com 0xA5 na criação da task. Em cada context switch, verifica os últimos N bytes. Se diferirem de 0xA5, a stack transbornou. vApplicationStackOverflowHook() é chamada para logging/halt." },
  { id: "fp-26", text: "O que é ETM (Embedded Trace Macrocell) no ARM Cortex-M?", options: ["Módulo de encryption de memória", "Unidade de trace que captura cada instrução executada em tempo real para profiling e debugging pós-mortem — requer interface de trace (TPIU + ETB ou Trace Port)", "Interface de programação alternativa ao JTAG", "Módulo de inicialização de tensão (power-on reset)"], correctIndex: 1, explanation: "ETM + Trace Port Analyzer: captura todas as instruções executadas. Ferramentas (Keil ULINKpro, Lauterbach TRACE32) reconstroem o fluxo de execução completo. Essencial para depuração de timing e análise de cobertura de código." },
  { id: "fp-27", text: "Mutex vs semáforo binário em FreeRTOS: qual a diferença chave?", options: ["Nenhuma diferença funcional", "Mutex tem priority inheritance (herança de prioridade) para evitar inversão de prioridade; semáforo binário não tem", "Mutex é para IPC entre processos; semáforo é para dentro de uma task", "Mutex pode ser usado de ISR; semáforo não"], correctIndex: 1, explanation: "Priority inheritance: quando task de baixa prioridade segura mutex, sua prioridade é temporariamente elevada à da task de alta prioridade que está esperando — evita inversão de prioridade. Semáforo binário não faz isso." },
  { id: "fp-28", text: "O que é 'linker script' e qual seu papel no build de firmware ARM?", options: ["Script de automação de testes", "Arquivo de texto (.ld) que instrui o linker sobre como organizar seções (.text, .data, .bss) nos endereços físicos de Flash e SRAM do microcontrolador específico", "Arquivo de configuração do compilador (flags de otimização)", "Script de programação do bootloader"], correctIndex: 1, explanation: "Linker script define: MEMORY {FLASH(rx): ORIGIN=0x08000000, LENGTH=512K; RAM(rwx): ORIGIN=0x20000000, LENGTH=128K;} e SECTIONS {.text > FLASH; .data > RAM AT> FLASH; .bss > RAM}." },
  { id: "fp-29", text: "O que é 'secure boot' em microcontroladores modernos?", options: ["Apenas cifração de comunicação serial", "Cadeia de verificação criptográfica no boot: ROM verifica assinatura do 1° estágio, que verifica o 2° estágio e assim por diante. Só firmware assinado pela chave privada do fabricante executa", "Senha de acesso ao JTAG", "Processo de geração de chaves AES no factory"], correctIndex: 1, explanation: "Secure boot chain: ROM imutável (ROM BL) → verifica assinatura do 1st stage BL → 2nd stage → RTOS/app. Chave pública na OTP Flash. Garante autenticidade e integridade do firmware contra tampering." },
  { id: "fp-30", text: "Qual é o benefício de usar __attribute__((section('.ccmram'))) em STM32F4?", options: ["Coloca código na Flash de alta velocidade", "Aloca variável ou função na CCM (Core Coupled Memory) SRAM — memória de acesso em ciclo zero de latência para a CPU, máxima performance para buffers DMA e stacks críticas", "Desabilita cache de instrução para aquela função", "Marca a função como interrupção"], correctIndex: 1, explanation: "STM32F4 CCM: 64 KB de SRAM acessível em 0 wait states pela CPU (mas não pelo DMA bus matrix). Ideal para stacks FreeRTOS de alta prioridade, buffers de cálculo DSP, tabelas de lookup." },
];

// Trilha 9 — IoT & Cloud Pro
const IOT_PRO: Question[] = [
  { id: "ip-01", text: "No AWS IoT Core, o endpoint MQTT de um dispositivo tem formato:", options: ["mqtt://iotcore.amazonaws.com", "xxxxxxxxxxxxxxx.iot.<região>.amazonaws.com — endpoint único por conta AWS", "mqtt.aws.com:8883", "iot.amazonaws.com/<device-id>"], correctIndex: 1, explanation: "AWS IoT Core endpoint: <account-prefix>.iot.<region>.amazonaws.com. Obtido via CLI: aws iot describe-endpoint --endpoint-type iot:Data-ATS. TLS obrigatório na porta 8883." },
  { id: "ip-02", text: "O Device Shadow no AWS IoT Core é usado para:", options: ["Armazenar firmware do dispositivo", "Manter o estado desejado (desired) e o estado reportado (reported) do dispositivo na nuvem, permitindo sincronização mesmo quando o dispositivo está offline", "Provisionar certificados X.509 automaticamente", "Fazer OTA updates"], correctIndex: 1, explanation: "Shadow JSON: {desired:{led:on}, reported:{led:off}, delta:{led:on}}. Dispositivo assina $aws/things/<name>/shadow/update/delta; quando reconecta, recebe o delta e atualiza seu estado." },
  { id: "ip-03", text: "Azure IoT Hub usa qual protocolo nativo para dispositivos além de MQTT?", options: ["CoAP apenas", "AMQP (Advanced Message Queuing Protocol) e HTTP além de MQTT — todos com TLS e autenticação SAS token ou X.509", "WebSocket exclusivamente", "MQTT sem TLS na porta 1883"], correctIndex: 1, explanation: "Azure IoT Hub: MQTT (porta 8883), AMQP (porta 5671), HTTPS (porta 443). AMQP é preferido para dispositivos com múltiplos canais lógicos. SDK IoT da Microsoft suporta todos os três." },
  { id: "ip-04", text: "DPS (Device Provisioning Service) no Azure IoT Hub resolve o problema de:", options: ["Atualização de firmware em escala", "Provisionamento automático em escala: dispositivos com certificado X.509 ou TPM se registram automaticamente no IoT Hub correto sem configuração manual de connection string", "Monitoramento de métricas de dispositivos", "Roteamento de mensagens para funções serverless"], correctIndex: 1, explanation: "DPS: fábrica grava chave/certificado de atestação no dispositivo. Na primeira conexão, DPS verifica identidade e aloca o dispositivo ao IoT Hub configurado. Zero-touch provisioning para milhões de devices." },
  { id: "ip-05", text: "Autenticação mútua TLS (mTLS) em IoT significa:", options: ["Apenas o cliente autentica o servidor via certificado CA", "Tanto o cliente (dispositivo) quanto o servidor apresentam certificados X.509 — autenticação bidirecional", "TLS sem verificação de certificado", "Uso de senha adicional além do certificado"], correctIndex: 1, explanation: "mTLS: dispositivo tem certificado de cliente assinado pela CA do AWS/Azure. Servidor também apresenta seu certificado. Impede man-in-the-middle e garante que apenas dispositivos legítimos com certificado válido se conectem." },
  { id: "ip-06", text: "MQTT sobre TLS usa qual porta padrão?", options: ["1883", "8883", "443", "5683"], correctIndex: 1, explanation: "MQTT: 1883 (sem TLS — uso apenas em rede local). MQTT+TLS: 8883 (recomendado para IoT em nuvem). MQTT+WebSocket+TLS: 443 (para atravessar firewalls corporativos). CoAP: 5683/5684." },
  { id: "ip-07", text: "AWS IoT Rules Engine permite:", options: ["Executar código C++ em dispositivos", "Criar regras SQL que filtram mensagens MQTT e acionam ações (Lambda, DynamoDB, S3, SNS, etc.) baseadas no conteúdo das mensagens", "Provisionar hardware remotamente", "Programar atualizações de firmware via console"], correctIndex: 1, explanation: "IoT Rule: SELECT temperature FROM 'sensors/+/temp' WHERE temperature > 80. Ações: invocar Lambda (alertar), gravar no DynamoDB (persistir), publicar SNS (notificar). SQL sobre JSON das mensagens MQTT." },
  { id: "ip-08", text: "O formato de linha (line protocol) do InfluxDB para gravar temperatura é:", options: ["INSERT INTO sensors (temp) VALUES (25.3) WHERE device='esp32'", "sensor_data,device=esp32 temperature=25.3 1609459200000000000", "{\"measurement\":\"sensor_data\",\"temperature\":25.3}", "temperature:25.3@esp32:1609459200"], correctIndex: 1, explanation: "Line Protocol: <measurement>[,tag_key=tag_value...] field_key=field_value[,field_key2=field_value2...] [timestamp_ns]. Tags: indexados para queries. Fields: dados numéricos/string." },
  { id: "ip-09", text: "Em InfluxDB, a diferença entre tag e field é:", options: ["Tags são numéricas; fields são texto", "Tags são indexadas (strings) para filtros rápidos e agrupamentos; fields contêm os valores de dados (numérico/string) não indexados", "Tags são opcionais; fields são obrigatórios e indexados", "Tags são permanentes; fields variam por ponto"], correctIndex: 1, explanation: "Tags (device=esp32, location=sala): indexadas, usadas em WHERE e GROUP BY, valores de baixa cardinalidade. Fields (temp=25.3, humidity=60.1): valores que variam por ponto, não indexados — todos os dados de série temporal." },
  { id: "ip-10", text: "TimescaleDB é um banco de dados de série temporal baseado em:", options: ["MongoDB (NoSQL)", "InfluxDB fork", "PostgreSQL — extensão que adiciona hypertables (particionamento temporal automático) ao PostgreSQL padrão", "Apache Cassandra"], correctIndex: 2, explanation: "TimescaleDB: PostgreSQL com hypertables. SELECT queries funcionam em SQL padrão. Compressão nativa (90%+ de redução). Suporta JOINs com tabelas relacionais — ideal para IoT com dados relacionais (dispositivos, usuários, locais)." },
  { id: "ip-11", text: "Grafana conecta a múltiplas fontes de dados (InfluxDB, Prometheus, MySQL) via:", options: ["Conversão prévia para CSV", "Data Source plugins configuráveis com URLs, credenciais e query builders específicos por banco", "Importação manual de JSON", "API REST única padronizada"], correctIndex: 1, explanation: "Grafana: instale data source plugin (InfluxDB, Prometheus, TimescaleDB, AWS CloudWatch...), configure URL e credenciais. Panel queries usam o dialeto de cada fonte (InfluxQL, PromQL, SQL)." },
  { id: "ip-12", text: "Ao criar alerta no Grafana, o estado 'Pending' significa:", options: ["O alerta foi enviado mas não confirmado", "A condição de alerta foi atingida mas o tempo de 'for duration' ainda não expirou — evita alertas falsos de spikes momentâneos", "O webhook de notificação falhou", "O painel está carregando dados"], correctIndex: 1, explanation: "Grafana alert: threshold > X 'for 5m'. Se condição atingida < 5 min → Pending. Se mantida por 5 min → Alerting (dispara notificação). Volta a OK se condição resolver. Evita alert storms de ruído." },
  { id: "ip-13", text: "O tamanho da arena (tensor arena) no TFLite Micro deve ser:", options: ["Sempre 1 MB fixo", "Calculado empiricamente — suficiente para os tensores de entrada, saída e intermediários do modelo. Use GetRequiredBufferSize() ou tente com tamanho maior e veja o mínimo necessário", "Igual ao tamanho do arquivo .tflite", "512 bytes para qualquer modelo de ML embarcado"], correctIndex: 1, explanation: "Arena size: soma de todos os tensores temporários durante inferência. Começa com 128 KB e usa kTfLiteStatus para detectar erro de arena insuficiente. Modelos MobileNetV1 tiny: ~300 KB. Person detection: ~100 KB." },
  { id: "ip-14", text: "Quantização INT8 em modelos de ML para edge reduz o modelo porque:", options: ["Remove camadas desnecessárias do modelo", "Pesos de float32 (4 bytes) são convertidos para int8 (1 byte) — redução 4x no tamanho e 2–4x na inferência, com perda < 2% de acurácia típica", "Usa compressão ZIP nos pesos", "Elimina operações de batch normalization"], correctIndex: 1, explanation: "Post-training quantization: calibra escala de cada camada com dataset representativo. float32 → int8 reduz de 1 MB para 250 KB típico. ARM CMSIS-NN acelera int8 com SIMD no Cortex-M4/M7." },
  { id: "ip-15", text: "Knowledge distillation em ML embarcado é técnica para:", options: ["Converter modelos ONNX para TFLite", "Treinar um modelo compacto (student) usando as saídas suavizadas de um modelo grande (teacher) como labels adicionais, transferindo conhecimento sem transferir tamanho", "Compressão de pesos com SVD", "Poda (pruning) de neurônios inativos"], correctIndex: 1, explanation: "Distillation: modelo grande teacher tem acurácia alta. Student menor treinado com soft labels do teacher (distribuição de probabilidade em vez de one-hot) aprende melhor com menos parâmetros." },
  { id: "ip-16", text: "O formato ONNX (Open Neural Network Exchange) é usado para:", options: ["Treinar modelos de ML online", "Exportar modelos de qualquer framework (PyTorch, TF, Keras) para um formato intermediário padrão que pode ser compilado para edge com ONNX Runtime, TFLite, TensorRT", "Compactar datasets de treinamento", "Sincronizar parâmetros entre workers de treinamento distribuído"], correctIndex: 1, explanation: "ONNX: modelo independente de framework. PyTorch → ONNX → ONNX Runtime Embedded (ARM) ou → TFLite (via onnx-tf converter) → MCU. Permite treinar no melhor framework e deployar na melhor plataforma." },
  { id: "ip-17", text: "OpenCV Mat (Matrix) no contexto de visão computacional embarcada armazena:", options: ["Apenas dados de vídeo H.264", "Imagem como array N-dimensional com tipo de dado configurável (CV_8UC3=3 canais uint8, CV_32FC1=float grayscale) e API de operações matriciais", "Modelo de rede neural", "Dados de telemetria de sensores"], correctIndex: 1, explanation: "cv::Mat img(480, 640, CV_8UC3): 640×480 pixels, BGR uint8. mat.at<Vec3b>(y,x) = pixel. Operações: resize, cvtColor(BGR→Grayscale), GaussianBlur, Canny, contornos, etc. Base do OpenCV." },
  { id: "ip-18", text: "Container Docker difere de VM (Virtual Machine) porque:", options: ["Containers são mais lentos que VMs", "Containers compartilham o kernel do host OS (namespace isolation); VMs virtualizam hardware completo com SO guest separado. Containers: menor overhead (~MB), inicialização em ms", "Containers só funcionam no Linux", "VMs são mais seguras que containers em todos os aspectos"], correctIndex: 1, explanation: "Docker: namespaces + cgroups do Linux. Processo isolado mas no mesmo kernel. Imagem = camadas. VM: hypervisor virtualiza CPU/RAM/disco, roda SO completo. Container: 50 MB, boot <1s. VM: 10 GB, boot 30s." },
  { id: "ip-19", text: "Docker Compose para stack IoT (MQTT broker + InfluxDB + Grafana) permite:", options: ["Apenas rodar em Kubernetes", "Definir múltiplos containers em um docker-compose.yml com redes, volumes e dependências, iniciando tudo com um único 'docker compose up'", "Substituir o sistema operacional do gateway", "Compilar firmware automaticamente"], correctIndex: 1, explanation: "docker-compose.yml: services: mosquitto, influxdb, grafana. Cada serviço com imagem, portas, volumes e networks. 'docker compose up -d' inicia todos em background. Essencial para IoT gateways." },
  { id: "ip-20", text: "K3s é:", options: ["Um protocolo IoT similar ao MQTT", "Uma distribuição Kubernetes leve (~70 MB) para edge e ARM, projetada para IoT gateways, Raspberry Pi e servers com recursos limitados", "Uma linguagem de programação para edge AI", "Um tipo de antena IoT de baixa potência"], correctIndex: 1, explanation: "K3s (Rancher Labs): Kubernetes completo mas com: SQLite em vez de etcd, sem cloud providers embutidos, binário único. Instala em 30s no RPi. Permite orquestrar containers em redes de gateways IoT." },
  { id: "ip-21", text: "OTA com rollback automático em IoT funciona quando:", options: ["O usuário confirma manualmente via app", "O novo firmware falha (watchdog, boot loop, CRC inválido) — o bootloader detecta e reverte para a partição anterior confirmada como boa", "A bateria chega a 20%", "O dispositivo perde conexão WiFi durante o update"], correctIndex: 1, explanation: "A/B OTA: partição A = boa. Baixa firmware para partição B. Inicializa B. Se B não confirmar (app_update_mark_valid_cancel()) dentro de N boots → bootloader reverte para A. Previne bricks em campo." },
  { id: "ip-22", text: "Certificate pinning em conexão TLS IoT significa:", options: ["Renovar certificados automaticamente", "O firmware do dispositivo verifica o fingerprint/hash específico do certificado do servidor, rejeitando certificados válidos mas diferentes — proteção contra CA comprometida", "Gerar certificados no dispositivo", "Aceitar qualquer certificado assinado por CA confiável"], correctIndex: 1, explanation: "Pinning: hardcode do hash SHA-256 do certificado do servidor no firmware. Se o servidor apresentar certificado diferente (mesmo válido por CA), conexão é recusada. Proteção contra ataques de CA intermediária." },
  { id: "ip-23", text: "STRIDE é um modelo de ameaças usado em IoT security para identificar:", options: ["Tipos de protocolos IoT", "6 categorias: Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service, Elevation of Privilege — framework sistemático para analisar riscos de segurança", "Arquiteturas de hardware seguro", "Algoritmos de criptografia recomendados"], correctIndex: 1, explanation: "STRIDE: S=falsificação de identidade, T=adulteração de dados, R=negação de ações, I=vazamento de informação, D=negação de serviço, E=elevação de privilégio. Aplicado em threat modeling para cada componente do sistema IoT." },
  { id: "ip-24", text: "TPM (Trusted Platform Module) em dispositivos IoT é usado principalmente para:", options: ["Armazenar firmware de backup", "Armazenar chaves criptográficas em hardware seguro, realizar operações criptográficas dentro do chip (sem expor chaves à CPU), e fornecer atestação de hardware remota", "Acelerar conexões TLS", "Servir como ADC de alta precisão"], correctIndex: 1, explanation: "TPM 2.0: gera e guarda chaves que nunca saem do chip. Assina dados com chave privada privada internamente. Remote attestation: prova ao servidor que o firmware não foi adulterado com PCR measurements." },
  { id: "ip-25", text: "O padrão de telemetria, comando e twin (Device Twin/Shadow) em IoT organiza a comunicação como:", options: ["Um único tópico MQTT para tudo", "Telemetry: device→cloud (dados de sensor); Command: cloud→device (ações); Twin/Shadow: estado sincronizado bidirecional (configuração e estado atual)", "REST API exclusivamente", "WebSocket bidirecional único"], correctIndex: 1, explanation: "Padrões IoT: Telemetry (D2C, alta frequência, dados brutos), Commands (C2D, baixa frequência, ações imediatas como ligar/desligar), Twin (D2C+C2D, estado durável como configuração de threshold, taxa de envio)." },
  { id: "ip-26", text: "Edge Computing vs Cloud Computing para IoT: a principal vantagem do edge é:", options: ["Menor custo de hardware", "Latência reduzida (ms vs 100ms+ para nuvem), processamento local de dados sensíveis (sem enviar ao servidor), funciona sem internet e reduz custos de banda", "Maior capacidade de armazenamento", "Facilidade de atualização de software"], correctIndex: 1, explanation: "Edge: factory automation (<1ms), visão computacional in-loco, dados de saúde que não podem sair do local. Trade-off: edge tem capacidade computacional limitada vs cloud elasticidade infinita." },
  { id: "ip-27", text: "AWS Greengrass (v2) em IoT Gateway permite:", options: ["Apenas relay de mensagens MQTT", "Executar funções Lambda, containers Docker e componentes Greengrass localmente no gateway, com sincronização para AWS IoT Core quando conectado", "Apenas atualização OTA de firmware", "Provisionar certificados X.509 automaticamente"], correctIndex: 1, explanation: "Greengrass v2: JVM na borda. Componentes (Lambdas, streams, ML inference) rodam localmente. Gerenciados via deployment do console AWS. Ideal para processamento em tempo real local + sync com nuvem." },
  { id: "ip-28", text: "Qual é a diferença entre MQTT e AMQP para IoT de alta escala?", options: ["São protocolos idênticos com nomes diferentes", "MQTT: simples, binário, pub/sub, ideal para sensores restritos. AMQP: mais robusto, suporta filas, acknowledgments, transações, routing complexo — ideal para middleware IoT de alta confiabilidade", "AMQP é mais leve que MQTT", "MQTT só funciona com brokers open source"], correctIndex: 1, explanation: "MQTT: overhead de 2 bytes de cabeçalho fixo, design simplificado para MCUs. AMQP: exchanges, queues, bindings, dead-letter queues, confirmações de entrega — usado em sistemas bancários e industriais críticos (RabbitMQ)." },
  { id: "ip-29", text: "InfluxDB Flux query para calcular média de temperatura por hora das últimas 24h:", options: ["SELECT avg(temperature) FROM sensors WHERE time > now()-24h GROUP BY 1h", "from(bucket:\"iot\") |> range(start:-24h) |> filter(fn:(r) => r._measurement == \"temp\") |> aggregateWindow(every:1h, fn:mean)", "GET /api/v2/query?bucket=iot&range=24h&agg=mean&window=1h", "influx query 'SELECT mean(temperature) WHERE time>-24h GROUPBY time(1h)'"], correctIndex: 1, explanation: "InfluxDB 2.x usa Flux (linguagem funcional). from → range → filter → aggregateWindow. Cada step é uma transformação de tabela. InfluxQL ainda suportado mas Flux é mais poderoso para joins e operações complexas." },
  { id: "ip-30", text: "Zero-touch provisioning em IoT em escala usa qual combinação de tecnologias?", options: ["Apenas WiFi Manager web portal", "DPS (Azure) ou Fleet Provisioning (AWS) + X.509 client certificates embutidos na fábrica + enrollment groups para aceitar qualquer dispositivo com certificado da CA do fabricante", "DHCP + mDNS automático", "QR code escaneado pelo instalador"], correctIndex: 1, explanation: "Fluxo: fábrica instala certificado de cliente (CA hierárquica). Primeira conexão ao DPS/Fleet Provisioning: verifica cert → cria Thing/Device no IoT Hub → retorna connection string permanente. Zero intervenção humana." },
];

